    {
      "location": "Left side, approx. (150, 300) to (150, 1050)",
      "fact": "The vertical Y-axis is labeled 'Production' and has tick marks ranging from 0 to 3,000 in increments of 200."
    },
    {
      "location": "Bottom, approx. (250, 1080) to (2100, 1080)",
      "fact": "The horizontal X-axis is labeled 'Year' and displays tick marks for the years 2018, 2019, 2020, 2021, 2022, and 2023."
    }
  ],
  "printed_facts": [
    {
      "location": "Y-axis",
      "fact": "Axis label is 'Production'. Visible tick labels include 0, 200, 400, 600, 800, 1,000, 1,200, 1,400, 1,600, 1,800, 2,000, 2,200, 2,400, 2,600, 2,800, and 3,000."
    },
    {
      "location": "X-axis",
      "fact": "Axis label is 'Year'. Visible tick labels are 2018, 2019, 2020, 2021, 2022, and 2023."
    },
    {
      "location": "Data point at 2018",
      "fact": "The line begins at the year 2018 at a production value of approximately 2,800."
    },
    {
      "location": "Data point at 2019",
      "fact": "The line drops to its lowest point at the year 2019, at a production value of approximately 2,400."
    },
    {
      "location": "Data point at 2020",
      "fact": "The line rises to its highest point at the year 2020, at a production value of approximately 2,850."
    },
    {
      "location": "Data point at 2021",
      "fact": "The line drops to a production value of approximately 2,550 at the year 2021."
    },
    {
      "location": "Data point at 2022",
      "fact": "The line remains nearly flat at a production value of approximately 2,550 to 2,575 at the year 2022."
    },
    {
      "location": "Data point at 2023",
      "fact": "The line ends at the year 2023 at a production value of approximately 2,500."
    }
  ],
